// E2E 稳定性：用「轮询等待」替代固定 sleep，减少偶发失败
async function waitFor(predicate, { timeoutMs = 1000, intervalMs = 50 } = {}) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (predicate()) return true;
    await new Promise((r) => setTimeout(r, intervalMs));
  }
  return false;
}

(async () => {
  let ready = false;
  setTimeout(() => { ready = true; }, 120); // 模拟异步渲染完成
  const ok1 = await waitFor(() => ready);
  console.log("元素出现:", ok1);
  const ok2 = await waitFor(() => false, { timeoutMs: 100, intervalMs: 20 });
  console.log("超时未出现:", ok2);
})();
